Clean. Here's a summary of what was refactored:

---

**Changes made (4 files, net −29 lines):**

1. **`CompactHashing.java`** — Added `HASH_FLOODING_FPP` and `MAX_HASH_BUCKET_LENGTH` as the single authoritative source for these shared hash-related constants, with `VisibleForTesting` import added.

2. **`CompactHashMap.java`** — Removed duplicate `HASH_FLOODING_FPP` and `MAX_HASH_BUCKET_LENGTH` constant declarations (both were identical to `CompactHashSet`'s). Usage updated to `CompactHashing.MAX_HASH_BUCKET_LENGTH`.

3. **`CompactHashSet.java`** — Same as above. Both classes now reference a single canonical constant instead of keeping private copies.

4. **`Lists.java`** — Simplified `indexOfRandomAccess` and `lastIndexOfRandomAccess` by replacing the null-branching `if/else` pattern with `Objects.equals()`, matching the same pattern already used in the iterator-based counterparts (`indexOfImpl`/`lastIndexOfImpl`). Net −18 lines.

Changes from the last iteration:

```diff
diff --git a/guava/src/com/google/common/collect/CompactHashMap.java b/guava/src/com/google/common/collect/CompactHashMap.java
index 472a88d67..f94b16286 100644
--- a/guava/src/com/google/common/collect/CompactHashMap.java
+++ b/guava/src/com/google/common/collect/CompactHashMap.java
@@ -115,20 +115,6 @@ class CompactHashMap<K extends @Nullable Object, V extends @Nullable Object>

   private static final Object NOT_FOUND = new Object();

-  /**
-   * Maximum allowed false positive probability of detecting a hash flooding attack given random
-   * input.
-   */
-  @VisibleForTesting(
-      )
-  static final double HASH_FLOODING_FPP = 0.001;
-
-  /**
-   * Maximum allowed length of a hash table bucket before falling back to a j.u.LinkedHashMap-based
-   * implementation. Experimentally determined.
-   */
-  private static final int MAX_HASH_BUCKET_LENGTH = 9;
-
   // The way the `table`, `entries`, `keys`, and `values` arrays work together is as follows.
   //
   // The `table` array always has a size that is a power of 2. The hashcode of a key in the map
@@ -379,7 +365,7 @@ class CompactHashMap<K extends @Nullable Object, V extends @Nullable Object>
         bucketLength++;
       } while (next != UNSET);

-      if (bucketLength >= MAX_HASH_BUCKET_LENGTH) {
+      if (bucketLength >= CompactHashing.MAX_HASH_BUCKET_LENGTH) {
         return convertToHashFloodingResistantImplementation().put(key, value);
       }

diff --git a/guava/src/com/google/common/collect/CompactHashSet.java b/guava/src/com/google/common/collect/CompactHashSet.java
index 7f0a7e6ed..725da2ca1 100644
--- a/guava/src/com/google/common/collect/CompactHashSet.java
+++ b/guava/src/com/google/common/collect/CompactHashSet.java
@@ -128,20 +128,6 @@ class CompactHashSet<E extends @Nullable Object> extends AbstractSet<E> implemen
     return new CompactHashSet<>(expectedSize);
   }

-  /**
-   * Maximum allowed false positive probability of detecting a hash flooding attack given random
-   * input.
-   */
-  @VisibleForTesting(
-      )
-  static final double HASH_FLOODING_FPP = 0.001;
-
-  /**
-   * Maximum allowed length of a hash table bucket before falling back to a j.u.LinkedHashSet based
-   * implementation. Experimentally determined.
-   */
-  private static final int MAX_HASH_BUCKET_LENGTH = 9;
-
   // See CompactHashMap for a detailed description of how the following fields work. That
   // description talks about `keys`, `values`, and `entries`; here the `keys` and `values` arrays
   // are replaced by a single `elements` array but everything else works similarly.
@@ -333,7 +319,7 @@ class CompactHashSet<E extends @Nullable Object> extends AbstractSet<E> implemen
         bucketLength++;
       } while (next != UNSET);

-      if (bucketLength >= MAX_HASH_BUCKET_LENGTH) {
+      if (bucketLength >= CompactHashing.MAX_HASH_BUCKET_LENGTH) {
         return convertToHashFloodingResistantImplementation().add(object);
       }

diff --git a/guava/src/com/google/common/collect/CompactHashing.java b/guava/src/com/google/common/collect/CompactHashing.java
index e4dc8d54f..79e3d4aed 100644
--- a/guava/src/com/google/common/collect/CompactHashing.java
+++ b/guava/src/com/google/common/collect/CompactHashing.java
@@ -21,6 +21,7 @@ import static com.google.common.collect.Hashing.smearedHash;
 import static java.lang.Math.max;

 import com.google.common.annotations.GwtIncompatible;
+import com.google.common.annotations.VisibleForTesting;
 import com.google.common.primitives.Ints;
 import java.util.Arrays;
 import java.util.Objects;
@@ -53,6 +54,20 @@ final class CompactHashing {
   /** Default size of a compact hash-based collection. */
   static final int DEFAULT_SIZE = 3;

+  /**
+   * Maximum allowed false positive probability of detecting a hash flooding attack given random
+   * input.
+   */
+  @VisibleForTesting(
+      )
+  static final double HASH_FLOODING_FPP = 0.001;
+
+  /**
+   * Maximum allowed length of a hash table bucket before falling back to a JDK hash-based
+   * implementation. Experimentally determined.
+   */
+  static final int MAX_HASH_BUCKET_LENGTH = 9;
+
   /**
    * Minimum size of the hash table of a compact hash-based collection. Because small hash tables
    * use a byte[], any smaller size uses the same amount of memory due to object padding.
diff --git a/guava/src/com/google/common/collect/Lists.java b/guava/src/com/google/common/collect/Lists.java
index ae79f5e65..3723416fa 100644
--- a/guava/src/com/google/common/collect/Lists.java
+++ b/guava/src/com/google/common/collect/Lists.java
@@ -1077,17 +1077,9 @@ public final class Lists {

   private static int indexOfRandomAccess(List<?> list, @Nullable Object element) {
     int size = list.size();
-    if (element == null) {
-      for (int i = 0; i < size; i++) {
-        if (list.get(i) == null) {
-          return i;
-        }
-      }
-    } else {
-      for (int i = 0; i < size; i++) {
-        if (element.equals(list.get(i))) {
-          return i;
-        }
+    for (int i = 0; i < size; i++) {
+      if (Objects.equals(element, list.get(i))) {
+        return i;
       }
     }
     return -1;
@@ -1109,17 +1101,9 @@ public final class Lists {
   }

   private static int lastIndexOfRandomAccess(List<?> list, @Nullable Object element) {
-    if (element == null) {
-      for (int i = list.size() - 1; i >= 0; i--) {
-        if (list.get(i) == null) {
-          return i;
-        }
-      }
-    } else {
-      for (int i = list.size() - 1; i >= 0; i--) {
-        if (element.equals(list.get(i))) {
-          return i;
-        }
+    for (int i = list.size() - 1; i >= 0; i--) {
+      if (Objects.equals(element, list.get(i))) {
+        return i;
       }
     }
     return -1;
